#include <iostream>
int main() {
    int amt = 41, coins = 0;
    int c[] = {25, 10, 5, 1};
    for (int x : c)
        while (amt >= x) { amt -= x; coins++; }
    std::cout << coins;
}

#include <iostream>
int main() {
    int w[] = {10, 20, 30}, v[] = {60, 100, 120};
    double best = 0;
    for (int i = 0; i < 3; i++)
        if ((double)v[i] / w[i] > best) best = (double)v[i] / w[i];
    std::cout << best;
}

#include <iostream>
#include <vector>
int main() {
    std::vector<std::pair<int, int>> v{{1, 2}, {2, 3}, {3, 4}, {0, 4}};
    int cnt = 0, last = -1;
    for (auto& p : v)
        if (p.first >= last) { cnt++; last = p.second; }
    std::cout << cnt;
}

#include <iostream>
int main() {
    int amt = 6, coins = 0;
    int c[] = {4, 3, 1};
    for (int x : c)
        while (amt >= x) { amt -= x; coins++; }
    std::cout << coins << " left " << amt;
}

#include <iostream>
int main() {
    int s[] = {1, 2, 6}, f[] = {4, 5, 8};
    int cnt = 0, last = -1;
    for (int i = 0; i < 3; i++)
        if (s[i] >= last) { cnt++; last = f[i]; }
    std::cout << cnt;
}

#include <algorithm>
#include <iostream>
#include <vector>
int main() {
    std::vector<std::pair<int, int>> ev{{1, 1}, {2, 1}, {4, -1}, {5, -1}};
    int cur = 0, best = 0;
    for (auto& e : ev) {
        cur += e.second;
        best = std::max(best, cur);
    }
    std::cout << best;
}
